const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').toLowerCase().trim();
const sessionId = body.sessionId || 'default';

const directIntents = [
  'admission','academic','contact','custom','back',
  'maternal','preescolar','primaria','secundaria',
  'bilingual','programs','axes','technology',
  'schedule_yes','schedule_no','admission_schedule'
];

let intent = directIntents.includes(message) ? message : null;

if (!intent) {
  if (/admisio|admision|inscripci/.test(message)) intent = 'admission';
  else if (/academi|estudio|oferta|programa/.test(message)) intent = 'academic';
  else if (/contacto|telefono|direccion|donde|ubicacion/.test(message)) intent = 'contact';
  else if (/hola|buenos|buenas|hey|hi/.test(message)) intent = 'back';
  else intent = 'custom';
}

return [{ json: { intent, sessionId, originalMessage: body.message || message } }];

