const data = $input.first().json;
const isCustom = data.intent === 'custom';
const text = isCustom
  ? 'Gracias por tu mensaje. Para una respuesta más detallada, contáctanos directamente:\n\n📞 +52 (333) 831-7000\n📧 info@lapaz.edu.mx\n\n¿En qué más puedo ayudarte?'
  : '¡Hola! Soy el asistente del Colegio La Paz. ¿En qué puedo ayudarte?';
return [{ json: { output: { text, options: [{ id: 'admission', label: '📝 Admisión' }, { id: 'academic', label: '📚 Información Académica' }, { id: 'contact', label: '📍 Contacto' }, { id: 'custom', label: '💬 Otra Pregunta' }] } } }];

const raw = $input.first().json;
const posts = (raw.data || []).slice(0, 6);

const classify = (msg) => {
  const m = (msg || '').toLowerCase();
  if (/evento|acto|ceremonia|festival|feria|graduaci|clausura|apertura|inauguraci/.test(m)) return 'event';
  if (/logro|campe|premio|medalla|triunfo|reconocimiento|primer lugar/.test(m)) return 'achievement';
  return 'news';
};

const fmtDate = iso => iso ? iso.split('T')[0] : '';

const getImage = att => {
  if (!att || !att.data || !att.data[0]) return '';
  const d = att.data[0];
  if (d.media && d.media.image && d.media.image.src) return d.media.image.src;
  const sub = d.subattachments && d.subattachments.data && d.subattachments.data[0];
  if (sub && sub.media && sub.media.image && sub.media.image.src) return sub.media.image.src;
  return '';
};

const result = posts.map((p, i) => {
  const msg   = (p.message || '').trim();
  const lines = msg.split('\n').filter(l => l.trim());
  const title = (lines[0] || ('Publicación ' + (i + 1))).substring(0, 80);
  const excerpt = msg.length > 140 ? msg.substring(0, 137) + '...' : msg;
  return {
    id:       i + 1,
    title,
    date:     fmtDate(p.created_time),
    platform: 'facebook',
    image:    getImage(p.attachments),
    excerpt,
    likes:    (p.likes && p.likes.summary    ? p.likes.summary.total_count    : 0),
    comments: (p.comments && p.comments.summary ? p.comments.summary.total_count : 0),
    type:     classify(msg)
  };
});

return result.map(item => ({ json: item }));
